def semver_sort(versions):
    def parse(v):
        # strip build metadata
        main_and_pre = v.split('+', 1)[0]
        if '-' in main_and_pre:
            main, pre = main_and_pre.split('-', 1)
        else:
            main, pre = main_and_pre, None

        parts = main.split('.')
        major, minor, patch = int(parts[0]), int(parts[1]), int(parts[2])

        if pre is None:
            has_pre = 1  # no prerelease sorts after
            ident_keys = ()
        else:
            has_pre = 0
            idents = pre.split('.')
            ident_keys = []
            for ident in idents:
                if ident.isdigit():
                    ident_keys.append((0, int(ident)))
                else:
                    ident_keys.append((1, ident))
            ident_keys = tuple(ident_keys)

        return (major, minor, patch, has_pre, ident_keys)

    indexed = list(enumerate(versions))
    indexed.sort(key=lambda pair: (parse(pair[1]), pair[0]))
    return [v for i, v in indexed]

